import{z as n,x as s,o as A,c as p,q as t,j as l,D as a,d as B,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"复现报告的写作","description":"","frontmatter":{"title":"复现报告的写作","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-report-writing.md","filePath":"llm/rw-report-writing.md","lastUpdated":1791063341000}'),d={name:"llm/rw-report-writing.md"};function D(m,E,F,C,h,c){const r=s("Mermaid");return A(),p("div",null,[E[2]||(E[2]=t('<h1 id="复现报告的写作" tabindex="-1">复现报告的写作 <a class="header-anchor" href="#复现报告的写作" aria-label="Permalink to &quot;复现报告的写作&quot;">​</a></h1><div class="epigraph"><p>复现研究的产物不是数字，是一份能让别人重新得到那些数字的记录；没有这份记录，数字只是传闻。</p><footer>—— 据 Peng, Reproducible Research and Biostatistics, 2011 整理</footer></div><p><a href="/llm/rw-open-source-upstream">上一课</a>把可送出的部分送回了上游；剩下不能送出的部分——对内的判定、置信度、死路档案——需要另一种载体。本课写复现报告。开源生态课有一篇同名课<a href="/llm/eco-repro-report-writing">复现报告的写作</a>，讲的是对外发布的可复现包规范；本课写它的对内对应物：一份回答「我们信什么、不信什么、为什么」的团队档案，让半年后的同事（以及忘记细节的你）能在十分钟内重建结论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复现做完不写，等于没做一半：判定散在会话记录、notebook 与聊天记录里，三个月后连自己都无法区分「验证过的主张」与「模糊的印象」。对内报告的缺口与对外报告不同：对外要说服陌生读者实验可信，对内要支撑团队决策——哪个结论可以引用、引用到哪一档、哪些坑不要再踩。把对外模板直接搬来用，会写出漂亮的废话：流程齐全，唯独没有一个数字能点回 run。</p><p><span class="marginnote">对内复现报告像医院的交接班记录：下一班医生要能从纸上知道「病人现在什么状态、哪些药试过无效、哪些结论已确认」。写「情况复杂」等于没写——正文说的「原因不明」悬空，就是这种空话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报告骨架六节，次序固定。一，声明：复用第一课那一页——类型、目标线、容差、范围、约束，一个字不改地引用，不重写。二，坐标系：代码 tag、配置哈希、数据指纹、硬件与镜像，全部是指针，指向账本而不是复制内容（<a href="/llm/ti-experiment-tracking">实验跟踪</a>的「指针不存副本」口径）。三，对齐账：四层锚点逐层列出——参考值、复现值、容差、判定，每个判定挂 run 链接；基线校准的最好努力与调参空间同节记档。四，决策表：判读一课的六行对照，标注披露档位与你补齐的决策。五，死路档案：归因六步走到的每条死路，死因落在判据上，同模板入库。六，结论分档：数字对上（强）、排序对上（中）、定性对上（弱）、未触及（无），下游决策按档位取用。</p><p>写作纪律三条：数字必带坐标，不出现裸分数；差异必带归因假设，不出现「原因不明」悬空；曲线与表格由权威工件生成后引用，不手抄截图。按决策组织，不按时间组织——「我们试了 A 又试了 B」是日记，「A 在容差内、B 在预算内不可判」才是报告。</p><p><span class="marginnote">数字实例：合格的一句判定是「pilot 级 loss 2.31，参考 2.28，差 0.03，容差 0.05，判对上，run 链接 r-9f3a」——数值、参考、容差、证据一句话齐活。对比「loss 差不多对上了」：三个月后没人知道这句话说了什么。</span></p>',10)),(A(),l(o,null,{default:a(()=>[i(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RPT%5B%22%E5%A4%8D%E7%8E%B0%E6%8A%A5%E5%91%8A%22%5D%20--%3E%20S1%5B%22%E5%A3%B0%E6%98%8E%EF%BC%9A%E7%B1%BB%E5%9E%8B%E4%B8%8E%E7%9B%AE%E6%A0%87%E7%BA%BF%22%5D%0A%20%20RPT%20--%3E%20S2%5B%22%E5%9D%90%E6%A0%87%E7%B3%BB%EF%BC%9A%E6%8C%87%E9%92%88%22%5D%0A%20%20RPT%20--%3E%20S3%5B%22%E5%AF%B9%E9%BD%90%E8%B4%A6%EF%BC%9A%E9%94%9A%E7%82%B9%2B%E5%AE%B9%E5%B7%AE%2B%E5%88%A4%E5%AE%9A%22%5D%0A%20%20RPT%20--%3E%20S4%5B%22%E5%86%B3%E7%AD%96%E8%A1%A8%EF%BC%9A%E5%85%AD%E8%A1%8C%2B%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20RPT%20--%3E%20S5%5B%22%E6%AD%BB%E8%B7%AF%E6%A1%A3%E6%A1%88%EF%BC%9A%E5%88%A4%E6%8D%AE%E8%90%BD%E6%A1%A3%22%5D%0A%20%20RPT%20--%3E%20S6%5B%22%E7%BB%93%E8%AE%BA%E5%88%86%E6%A1%A3%EF%BC%9A%E5%BC%BA%2F%E4%B8%AD%2F%E5%BC%B1%2F%E6%97%A0%22%5D%0A%20%20S3%20--%3E%20Q%5B%22%E6%96%B0%E8%AF%BB%E8%80%85%E9%87%8D%E5%BB%BA%E6%B5%8B%E8%AF%95%22%5D%0A%20%20S5%20--%3E%20Q%0A%20%20Q%20--%3E%7C%22%E9%87%8D%E5%BB%BA%E5%A4%B1%E8%B4%A5%E5%A4%84%22%7C%20FIX%5B%22%E6%94%B9%E5%86%99%E8%AF%A5%E8%8A%82%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"为什么死路档案是报告的核心资产：成功的对齐只证明「这条路径通」，死路才标记「哪些假设已被排除」。只写成功的报告会诱导团队在同一死路上再花一次算力——负结果可检索是归档课立过的规矩，报告是这条规矩的入口。为什么结论必须分档：下游引用「复现成功」时，实际取用的是不同的东西——强档支撑数值对标，中档支撑选型排序，弱档只支撑方向判断；不分档，最弱的那部分结论会搭着「已复现」三个字一起被引用，这是复现报告最常见的事故。",-1)),(A(),l(o,null,{default:a(()=>[i(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E7%BB%93%E8%AE%BA%E5%9B%9B%E6%A1%A3%22%5D%20--%3E%20A%5B%22%E5%BC%BA%EF%BC%9A%E6%95%B0%E5%AD%97%E5%AF%B9%E4%B8%8A%22%5D%0A%20%20G%20--%3E%20B%5B%22%E4%B8%AD%EF%BC%9A%E6%8E%92%E5%BA%8F%E5%AF%B9%E4%B8%8A%22%5D%0A%20%20G%20--%3E%20C%5B%22%E5%BC%B1%EF%BC%9A%E5%AE%9A%E6%80%A7%E5%AF%B9%E4%B8%8A%22%5D%0A%20%20G%20--%3E%20D%5B%22%E6%97%A0%EF%BC%9A%E6%9C%AA%E8%A7%A6%E5%8F%8A%22%5D%0A%20%20A%20--%3E%20U1%5B%22%E5%8F%AF%E5%BC%95%E7%94%A8%EF%BC%9A%E6%95%B0%E5%80%BC%E5%AF%B9%E6%A0%87%22%5D%0A%20%20B%20--%3E%20U2%5B%22%E5%8F%AF%E5%BC%95%E7%94%A8%EF%BC%9A%E9%80%89%E5%9E%8B%E6%8E%92%E5%BA%8F%22%5D%0A%20%20C%20--%3E%20U3%5B%22%E5%8F%AF%E5%BC%95%E7%94%A8%EF%BC%9A%E6%96%B9%E5%90%91%E5%88%A4%E6%96%AD%22%5D%0A%20%20D%20--%3E%20U4%5B%22%E4%B8%8D%E5%8F%AF%E5%BC%95%E7%94%A8%EF%BC%8C%E5%8F%AA%E8%AE%B0%E6%A1%A3%22%5D%0A%20%20U4%20--%3E%20W%5B%22%E9%98%B2%E6%90%AD%E8%BD%A6%EF%BC%9A%E4%B8%8D%E5%BE%97%E9%A1%B6%E7%9D%80%E3%80%8C%E5%B7%B2%E5%A4%8D%E7%8E%B0%E3%80%8D%E5%87%BA%E9%97%A8%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：报告只写「复现成功」，读者便默认整篇论文都被验证了。实际可能只有主表数字对上（强档），排序与机制声明都未触及（无档）。不写档位，最弱的部分就会搭车被一起引用。</span></p><p>报告的质量检验不是通读，是重建：找一个未参与的同事，只给报告与仓库，限时重建主表的一个数字。重建卡住的第一个位置，就是报告没写清的第一个位置——这句话对声明、对齐账与死路档案同样成立。</p><p><span class="marginnote">主报告控制在一页纸，证据全部放在附录链接后面。判断标准：评审者两分钟读完能说出「验证了什么、停在哪条线、还欠什么」；超时即报告结构有问题，而不是读者不认真。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>报告不替代可复现包：对外发布按生态课的规范另做，两者共享坐标系但读者不同。内部报告也有保密边界：私有评测集的名字与细节、受限数据的指纹用代称，不进可外传的版本。报告不写成追责文档：死路档案记录差异与判据，不记录「谁改错了配置」——一旦报告开始指认人，团队会停止记录失败，账本从此失真。最后，报告是活档案：上游 release、数据更新、后续复现者的新证据，都以增补形式追加并升版，不覆盖原文——判定可以翻案，翻案要留痕。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>骨架六节：声明、坐标系、对齐账、决策表、死路档案、结论分档；次序固定。</li><li>数字带坐标、差异带归因假设、工件用指针不截图；按决策组织不按时间组织。</li><li>死路档案是核心资产：排除记录是团队跳过重复算力的凭据。</li><li>结论分四档，下游按档取用；不分档会让弱结论搭车被引用。</li><li>质检是新读者重建测试：重建失败处即写作失败处。</li><li>出处：Peng, 2011；对包规范见<a href="/llm/eco-repro-report-writing">复现报告的写作</a>，归档纪律见<a href="/llm/ti-failed-exp-archive">失败实验的归档</a>。</li></ul>',7))])}const _=n(d,[["render",D]]);export{u as __pageData,_ as default};
